class Solution {
    public String abbreviateProduct(int left, int right) {
        final long MOD = 10_000_000_000L;

        int count2 = 0;
        int count5 = 0;
        double logProduct = 0.0;
        long remainingMod = 1;

        for (int i = left; i <= right; i++) {
            logProduct += Math.log10(i);

            int value = i;
            while (value % 2 == 0) {
                count2++;
                value /= 2;
            }
            while (value % 5 == 0) {
                count5++;
                value /= 5;
            }

            remainingMod = (remainingMod * value) % MOD;
        }

        int zeros = Math.min(count2, count5);
        int extra2 = count2 - zeros;
        int extra5 = count5 - zeros;

        for (int i = 0; i < extra2; i++) {
            remainingMod = (remainingMod * 2) % MOD;
        }
        for (int i = 0; i < extra5; i++) {
            remainingMod = (remainingMod * 5) % MOD;
        }

        double remainingLog = logProduct - zeros;
        int digits = (int) Math.floor(remainingLog) + 1;

        if (digits <= 10) {
            return remainingMod + "e" + zeros;
        }

        double fractional = remainingLog - Math.floor(remainingLog);
        long prefix = (long) Math.pow(10, fractional + 4);
        if (prefix >= 100000) {
            prefix = 99999;
        }

        long suffix = remainingMod % 100000;
        StringBuilder suffixString = new StringBuilder();
        for (int i = 0; i < 5 - String.valueOf(suffix).length(); i++) {
            suffixString.append('0');
        }
        suffixString.append(suffix);

        return prefix + "..." + suffixString + "e" + zeros;
    }
}
