class Solution {
    public int maxSizeSlices(int[] slices) {
        int n = slices.length / 3;
        int option1 = solveLinear(slices, 0, slices.length - 2, n);
        int option2 = solveLinear(slices, 1, slices.length - 1, n);
        return Math.max(option1, option2);
    }

    private int solveLinear(int[] slices, int start, int end, int picks) {
        int length = end - start + 1;
        int negative = Integer.MIN_VALUE / 2;
        int[][] dp = new int[length + 1][picks + 1];

        for (int i = 0; i <= length; i++) {
            for (int j = 0; j <= picks; j++) {
                dp[i][j] = negative;
            }
            dp[i][0] = 0;
        }

        for (int i = 1; i <= length; i++) {
            dp[i][0] = 0;
            for (int j = 1; j <= picks; j++) {
                dp[i][j] = dp[i - 1][j];

                if (i >= 2 && dp[i - 2][j - 1] != negative) {
                    dp[i][j] = Math.max(
                        dp[i][j],
                        dp[i - 2][j - 1] + slices[start + i - 1]
                    );
                }
            }
        }

        return dp[length][picks];
    }
}
