import java.util.*;

class Solution {
    public List<String> removeInvalidParentheses(String s) {
        Set<String> result = new HashSet<>();
        remove(s, 0, '(', ')', result);
        return new ArrayList<>(result);
    }

    private void remove(String s, int start, char open, char close, Set<String> result) {
        int balance = 0;

        for (int i = start; i < s.length(); i++) {
            char c = s.charAt(i);

            if (c == open) {
                balance++;
            } else if (c == close) {
                balance--;
            }

            if (balance >= 0) {
                continue;
            }

            for (int j = start; j <= i; j++) {
                if (s.charAt(j) == close &&
                    (j == start || s.charAt(j - 1) != close)) {
                    String next = s.substring(0, j) + s.substring(j + 1);
                    remove(next, j, open, close, result);
                }
            }

            return;
        }

        if (open == '(') {
            String reversed = new StringBuilder(s).reverse().toString();
            remove(reversed, 0, ')', '(', result);
        } else {
            result.add(new StringBuilder(s).reverse().toString());
        }
    }
}
