class Solution {
    public int minSteps(int n) {
        int result = 0;

        for (int factor = 2; factor * factor <= n; factor++) {
            while (n % factor == 0) {
                result += factor;
                n /= factor;
            }
        }

        if (n > 1) {
            result += n;
        }

        return result;
    }
}
