class Solution {
    public List<String> ambiguousCoordinates(String s) {
        List<String> result = new ArrayList<>();
        String digits = s.substring(1, s.length() - 1);

        for (int split = 1; split < digits.length(); split++) {
            String left = digits.substring(0, split);
            String right = digits.substring(split);

            List<String> leftParts = validNumbers(left);
            List<String> rightParts = validNumbers(right);

            for (String a : leftParts) {
                for (String b : rightParts) {
                    result.add("(" + a + ", " + b + ")");
                }
            }
        }

        return result;
    }

    private List<String> validNumbers(String part) {
        List<String> result = new ArrayList<>();

        if (part.length() == 1 || part.charAt(0) != '0') {
            result.add(part);
        }

        if (part.length() > 1 && part.charAt(part.length() - 1) != '0') {
            for (int i = 1; i < part.length(); i++) {
                String integerPart = part.substring(0, i);
                String fractionalPart = part.substring(i);

                if (integerPart.length() == 1 || integerPart.charAt(0) != '0') {
                    result.add(integerPart + "." + fractionalPart);
                }
            }
        }

        return result;
    }
}
