class Solution {
    public int[] hitBricks(int[][] grid, int[][] hits) {
        int m = grid.length;
        int n = grid[0].length;
        int total = m * n;
        int roof = total;

        boolean[] existed = new boolean[hits.length];
        for (int i = 0; i < hits.length; i++) {
            int r = hits[i][0];
            int c = hits[i][1];
            if (grid[r][c] == 1) {
                existed[i] = true;
                grid[r][c] = 0;
            }
        }

        DSU dsu = new DSU(total + 1);

        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 0) {
                    continue;
                }

                int index = r * n + c;
                if (r == 0) {
                    dsu.union(index, roof);
                }
                if (r > 0 && grid[r - 1][c] == 1) {
                    dsu.union(index, (r - 1) * n + c);
                }
                if (c > 0 && grid[r][c - 1] == 1) {
                    dsu.union(index, r * n + c - 1);
                }
            }
        }

        int[] result = new int[hits.length];

        for (int i = hits.length - 1; i >= 0; i--) {
            if (!existed[i]) {
                continue;
            }

            int before = dsu.size(dsu.find(roof));
            int r = hits[i][0];
            int c = hits[i][1];
            int index = r * n + c;

            grid[r][c] = 1;

            if (r == 0) {
                dsu.union(index, roof);
            }

            if (r > 0 && grid[r - 1][c] == 1) {
                dsu.union(index, (r - 1) * n + c);
            }
            if (r + 1 < m && grid[r + 1][c] == 1) {
                dsu.union(index, (r + 1) * n + c);
            }
            if (c > 0 && grid[r][c - 1] == 1) {
                dsu.union(index, r * n + c - 1);
            }
            if (c + 1 < n && grid[r][c + 1] == 1) {
                dsu.union(index, r * n + c + 1);
            }

            int after = dsu.size(dsu.find(roof));
            result[i] = Math.max(0, after - before - 1);
        }

        return result;
    }

    private static class DSU {
        private final int[] parent;
        private final int[] size;

        DSU(int n) {
            parent = new int[n];
            size = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        int find(int x) {
            while (parent[x] != x) {
                parent[x] = parent[parent[x]];
                x = parent[x];
            }
            return x;
        }

        void union(int a, int b) {
            int rootA = find(a);
            int rootB = find(b);

            if (rootA == rootB) {
                return;
            }

            if (size[rootA] < size[rootB]) {
                int temp = rootA;
                rootA = rootB;
                rootB = temp;
            }

            parent[rootB] = rootA;
            size[rootA] += size[rootB];
        }

        int size(int root) {
            return size[root];
        }
    }
}
