class Solution {
    public int clumsy(int n) {
        java.util.ArrayDeque<Long> stack = new java.util.ArrayDeque<>();
        stack.push((long) n);

        int operation = 0;
        for (int value = n - 1; value >= 1; value--) {
            if (operation == 0) {
                stack.push(stack.pop() * value);
            } else if (operation == 1) {
                stack.push(stack.pop() / value);
            } else if (operation == 2) {
                stack.push((long) value);
            } else {
                stack.push((long) -value);
            }

            operation = (operation + 1) % 4;
        }

        long result = 0;
        while (!stack.isEmpty()) {
            result += stack.pop();
        }

        return (int) result;
    }
}
