class Solution {
    public int countVowelSubstrings(String word) {
        int[] last = {-1, -1, -1, -1, -1};
        int segmentStart = 0;
        int result = 0;

        for (int i = 0; i < word.length(); i++) {
            int vowel = getVowelIndex(word.charAt(i));

            if (vowel == -1) {
                segmentStart = i + 1;
                last = new int[]{-1, -1, -1, -1, -1};
                continue;
            }

            last[vowel] = i;

            int earliestLast = Integer.MAX_VALUE;
            boolean allPresent = true;

            for (int position : last) {
                if (position == -1) {
                    allPresent = false;
                    break;
                }
                earliestLast = Math.min(earliestLast, position);
            }

            if (allPresent) {
                result += earliestLast - segmentStart + 1;
            }
        }

        return result;
    }

    private int getVowelIndex(char c) {
        switch (c) {
            case 'a': return 0;
            case 'e': return 1;
            case 'i': return 2;
            case 'o': return 3;
            case 'u': return 4;
            default: return -1;
        }
    }
}
