import java.util.ArrayDeque;
import java.util.Deque;
import java.util.TreeMap;

class MKAverage {
    private final int m;
    private final int k;
    private final Deque<Integer> window;
    private final TreeMap<Integer, Integer> low;
    private final TreeMap<Integer, Integer> middle;
    private final TreeMap<Integer, Integer> high;
    private int lowSize;
    private int middleSize;
    private int highSize;
    private long middleSum;

    public MKAverage(int m, int k) {
        this.m = m;
        this.k = k;
        this.window = new ArrayDeque<>();
        this.low = new TreeMap<>();
        this.middle = new TreeMap<>();
        this.high = new TreeMap<>();
    }

    public void addElement(int num) {
        window.offerLast(num);

        if (!low.isEmpty() && num <= low.lastKey()) {
            add(low, num);
            lowSize++;
        } else if (!high.isEmpty() && num >= high.firstKey()) {
            add(high, num);
            highSize++;
        } else {
            add(middle, num);
            middleSize++;
            middleSum += num;
        }

        if (window.size() > m) {
            int removed = window.pollFirst();

            if (low.containsKey(removed)) {
                remove(low, removed);
                lowSize--;
            } else if (high.containsKey(removed)) {
                remove(high, removed);
                highSize--;
            } else {
                remove(middle, removed);
                middleSize--;
                middleSum -= removed;
            }
        }

        rebalance();
    }

    public int calculateMKAverage() {
        if (window.size() < m) {
            return -1;
        }
        return (int) (middleSum / (m - 2L * k));
    }

    private void rebalance() {
        int targetLow = Math.min(k, window.size());
        int targetHigh = Math.min(k, window.size() - targetLow);

        while (lowSize > targetLow) {
            int value = low.lastKey();
            remove(low, value);
            lowSize--;
            add(middle, value);
            middleSize++;
            middleSum += value;
        }

        while (lowSize < targetLow) {
            if (middleSize > 0) {
                int value = middle.firstKey();
                remove(middle, value);
                middleSize--;
                middleSum -= value;
                add(low, value);
                lowSize++;
            } else if (highSize > 0) {
                int value = high.firstKey();
                remove(high, value);
                highSize--;
                add(middle, value);
                middleSize++;
                middleSum += value;
            }
        }

        while (highSize > targetHigh) {
            int value = high.firstKey();
            remove(high, value);
            highSize--;
            add(middle, value);
            middleSize++;
            middleSum += value;
        }

        while (highSize < targetHigh) {
            if (middleSize > 0) {
                int value = middle.lastKey();
                remove(middle, value);
                middleSize--;
                middleSum -= value;
                add(high, value);
                highSize++;
            } else if (lowSize > targetLow) {
                int value = low.lastKey();
                remove(low, value);
                lowSize--;
                add(middle, value);
                middleSize++;
                middleSum += value;
            }
        }
    }

    private void add(TreeMap<Integer, Integer> map, int value) {
        map.put(value, map.getOrDefault(value, 0) + 1);
    }

    private void remove(TreeMap<Integer, Integer> map, int value) {
        int count = map.get(value);
        if (count == 1) {
            map.remove(value);
        } else {
            map.put(value, count - 1);
        }
    }
}
