import java.util.HashMap;
import java.util.Map;

class Solution {
    public boolean canCross(int[] stones) {
        int n = stones.length;
        if (n == 2) {
            return stones[1] == 1;
        }
        if (stones[1] != 1) {
            return false;
        }

        Map<Integer, Integer> indexByPosition = new HashMap<>();
        for (int i = 0; i < n; i++) {
            indexByPosition.put(stones[i], i);
        }

        boolean[][] reachable = new boolean[n][n + 1];
        reachable[1][1] = true;

        for (int i = 1; i < n; i++) {
            for (int jump = 1; jump <= n; jump++) {
                if (!reachable[i][jump]) {
                    continue;
                }

                for (int nextJump = jump - 1; nextJump <= jump + 1; nextJump++) {
                    if (nextJump <= 0) {
                        continue;
                    }

                    long nextPosition = (long) stones[i] + nextJump;
                    if (nextPosition > Integer.MAX_VALUE) {
                        continue;
                    }

                    Integer nextIndex = indexByPosition.get((int) nextPosition);
                    if (nextIndex == null) {
                        continue;
                    }

                    if (nextIndex == n - 1) {
                        return true;
                    }

                    if (nextJump <= n) {
                        reachable[nextIndex][nextJump] = true;
                    }
                }
            }
        }

        return false;
    }
}
