    public String licenseKeyFormatting(String s, int k) {
        StringBuilder cleaned = new StringBuilder();

        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c != '-') {
                if (c >= 'a' && c <= 'z') {
                    c = (char) (c - 'a' + 'A');
                }
                cleaned.append(c);
            }
        }

        int n = cleaned.length();
        if (n == 0) {
            return "";
        }

        int firstGroupLength = n % k;
        if (firstGroupLength == 0) {
            firstGroupLength = k;
        }

        StringBuilder result = new StringBuilder(n + n / k);

        for (int i = 0; i < n; i++) {
            if (i > 0 && (i == firstGroupLength || (i > firstGroupLength && (i - firstGroupLength) % k == 0))) {
                result.append('-');
            }
            result.append(cleaned.charAt(i));
        }

        return result.toString();
    }
}
