            int bestFromPoint = 0;

            for (int j = i + 1; j < n; j++) {
                int dx = points[j][0] - points[i][0];
                int dy = points[j][1] - points[i][1];

                int gcd = gcd(Math.abs(dx), Math.abs(dy));
                dx /= gcd;
                dy /= gcd;

                if (dx < 0 || (dx == 0 && dy < 0)) {
                    dx = -dx;
                    dy = -dy;
                }

                String slope = dy + "#" + dx;
                int count = slopes.getOrDefault(slope, 0) + 1;
                slopes.put(slope, count);
                bestFromPoint = Math.max(bestFromPoint, count);
            }

            result = Math.max(result, bestFromPoint + 1);
        }

        return result;
    }

    private int gcd(int a, int b) {
        while (b != 0) {
            int temp = a % b;
            a = b;
            b = temp;
        }
        return a;
    }
