class Solution {
    private int[] nums;
    private int[] memo;
    private int fullMask;

    public int maxScore(int[] nums) {
        this.nums = nums;
        int size = nums.length;
        fullMask = (1 << size) - 1;
        memo = new int[1 << size];
        java.util.Arrays.fill(memo, -1);
        return dfs(0);
    }

    private int dfs(int mask) {
        if (mask == fullMask) {
            return 0;
        }
        if (memo[mask] != -1) {
            return memo[mask];
        }

        int operation = Integer.bitCount(mask) / 2 + 1;
        int best = 0;

        for (int i = 0; i < nums.length; i++) {
            if ((mask & (1 << i)) != 0) {
                continue;
            }

            for (int j = i + 1; j < nums.length; j++) {
                if ((mask & (1 << j)) != 0) {
                    continue;
                }

                int pairGcd = gcd(nums[i], nums[j]);
                int score = operation * pairGcd
                        + dfs(mask | (1 << i) | (1 << j));
                best = Math.max(best, score);
            }
        }

        return memo[mask] = best;
    }

    private int gcd(int a, int b) {
        while (b != 0) {
            int temp = a % b;
            a = b;
            b = temp;
        }
        return a;
    }
}
