class Solution {
    public int maximumANDSum(int[] nums, int numSlots) {
        int states = 1 << (2 * numSlots);
        int[][] memo = new int[nums.length][states];

        for (int[] row : memo) {
            Arrays.fill(row, -1);
        }

        return dfs(nums, numSlots, 0, 0, memo);
    }

    private int dfs(int[] nums, int numSlots, int index, int state, int[][] memo) {
        if (index == nums.length) {
            return 0;
        }

        if (memo[index][state] != -1) {
            return memo[index][state];
        }

        int best = 0;

        for (int slot = 0; slot < numSlots; slot++) {
            int shift = 2 * slot;
            int count = (state >> shift) & 3;

            if (count < 2) {
                int nextState = state + (1 << shift);
                int value = (nums[index] & (slot + 1))
                        + dfs(nums, numSlots, index + 1, nextState, memo);
                best = Math.max(best, value);
            }
        }

        return memo[index][state] = best;
    }
}
