        int firstZero = binary.indexOf('0');

        if (firstZero == -1) {
            return binary;
        }

        int zeroCount = 0;
        for (int i = firstZero; i < n; i++) {
            if (binary.charAt(i) == '0') {
                zeroCount++;
            }
        }

        StringBuilder result = new StringBuilder();
        for (int i = 0; i < n; i++) {
            result.append('1');
