class Solution {
    public int maxCompatibilitySum(int[][] students, int[][] mentors) {
        int m = students.length;
        int n = students[0].length;

        int[][] score = new int[m][m];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < m; j++) {
                for (int k = 0; k < n; k++) {
                    if (students[i][k] == mentors[j][k]) {
                        score[i][j]++;
                    }
                }
            }
        }

        int totalMasks = 1 << m;
        int[] dp = new int[totalMasks];
        for (int i = 1; i < totalMasks; i++) {
            dp[i] = -1;
        }

        for (int mask = 0; mask < totalMasks; mask++) {
            int student = Integer.bitCount(mask);
            if (student == m) {
                continue;
            }

            for (int mentor = 0; mentor < m; mentor++) {
                if ((mask & (1 << mentor)) == 0) {
                    int nextMask = mask | (1 << mentor);
                    dp[nextMask] = Math.max(dp[nextMask], dp[mask] + score[student][mentor]);
                }
            }
        }

        return dp[totalMasks - 1];
    }
}
