class Solution {
    public int maxEqualFreq(int[] nums) {
        int n = nums.length;
        int[] valueFrequency = new int[100001];
        int[] frequencyCount = new int[n + 1];

        int maxFrequency = 0;
        int answer = 0;

        for (int i = 0; i < n; i++) {
            int value = nums[i];
            int oldFrequency = valueFrequency[value];

            if (oldFrequency > 0) {
                frequencyCount[oldFrequency]--;
            }

            int newFrequency = ++valueFrequency[value];
            frequencyCount[newFrequency]++;

            maxFrequency = Math.max(maxFrequency, newFrequency);

            int length = i + 1;

            if (maxFrequency == 1) {
                answer = length;
            } else if (frequencyCount[maxFrequency] == 1
                    && frequencyCount[maxFrequency - 1] * (maxFrequency - 1)
                       + maxFrequency == length) {
                answer = length;
            } else if (frequencyCount[1] == 1
                    && frequencyCount[maxFrequency] * maxFrequency + 1 == length) {
                answer = length;
            }
        }

        return answer;
    }
}
