    public int maxTotalFruits(int[][] fruits, int startPos, int k) {
        int n = fruits.length;
        int left = 0;
        long sum = 0;
        long answer = 0;

        for (int right = 0; right < n; right++) {
            sum += fruits[right][1];

            while (left <= right && requiredSteps(
                    fruits[left][0],
                    fruits[right][0],
                    startPos
            ) > k) {
                sum -= fruits[left][1];
                left++;
            }

            answer = Math.max(answer, sum);
        }

        return (int) answer;
    }

    private long requiredSteps(int left, int right, int startPos) {
        if (right <= startPos) {
            return (long) startPos - left;
        }

        if (left >= startPos) {
            return (long) right - startPos;
        }

        long goLeftFirst = 2L * (startPos - left) + (right - startPos);
        long goRightFirst = (startPos - left) + 2L * (right - startPos);

        return Math.min(goLeftFirst, goRightFirst);
    }
}
