    public int maxSumTwoNoOverlap(int[] nums, int firstLen, int secondLen) {
        int n = nums.length;
        int[] prefix = new int[n + 1];

        for (int i = 0; i < n; i++) {
            prefix[i + 1] = prefix[i] + nums[i];
        }

        return Math.max(
            maxOrdered(prefix, n, firstLen, secondLen),
            maxOrdered(prefix, n, secondLen, firstLen)
        );
