        int bestLeft = 0;
        int result = 0;

        for (int rightStart = leftLen; rightStart + rightLen <= n; rightStart++) {
            int leftSum = prefix[rightStart] - prefix[rightStart - leftLen];
            bestLeft = Math.max(bestLeft, leftSum);

            int rightSum = prefix[rightStart + rightLen] - prefix[rightStart];
            result = Math.max(result, bestLeft + rightSum);
        }

        return result;
    }
}
