import java.util.Arrays;

class Solution {
    public long maximumBeauty(int[] flowers, long newFlowers, int target, int full, int partial) {
        int n = flowers.length;

        for (int i = 0; i < n; i++) {
            flowers[i] = Math.min(flowers[i], target);
        }
        Arrays.sort(flowers);

        long[] prefix = new long[n + 1];
        for (int i = 0; i < n; i++) {
            prefix[i + 1] = prefix[i] + flowers[i];
        }

        int incomplete = lowerBound(flowers, n, target);
        long completionCost = 0;
        long answer = 0;

        for (int extraFull = 0; extraFull <= incomplete; extraFull++) {
            if (completionCost > newFlowers) {
                break;
            }

            int remaining = incomplete - extraFull;
            int totalFull = n - remaining;
            long beauty = (long) totalFull * full;

            if (remaining > 0) {
                long budget = newFlowers - completionCost;
                int low = 0;
                int high = target - 1;
                int bestMinimum = 0;

                while (low <= high) {
                    int mid = low + (high - low) / 2;
                    int count = lowerBound(flowers, remaining, mid);
                    long needed = (long) mid * count - prefix[count];

                    if (needed <= budget) {
                        bestMinimum = mid;
                        low = mid + 1;
                    } else {
                        high = mid - 1;
                    }
                }

                beauty += (long) bestMinimum * partial;
            }

            answer = Math.max(answer, beauty);

            if (extraFull < incomplete) {
                completionCost += target - flowers[incomplete - 1 - extraFull];
            }
        }

        return answer;
    }

    private int lowerBound(int[] array, int length, int value) {
        int low = 0;
        int high = length;

        while (low < high) {
            int mid = low + (high - low) / 2;
            if (array[mid] < value) {
                low = mid + 1;
            } else {
                high = mid;
            }
        }

        return low;
    }
}
