    public int minMalwareSpread(int[][] graph, int[] initial) {
        int n = graph.length;
        boolean[] infected = new boolean[n];
        for (int node : initial) {
            infected[node] = true;
        }

        int[] parent = new int[n];
        int[] size = new int[n];
        for (int i = 0; i < n; i++) {
            parent[i] = i;
            size[i] = infected[i] ? 0 : 1;
        }

        for (int i = 0; i < n; i++) {
            if (infected[i]) continue;
            for (int j = i + 1; j < n; j++) {
                if (!infected[j] && graph[i][j] == 1) {
                    union(parent, size, i, j);
                }
            }
        }

        int[] owner = new int[n];
        for (int i = 0; i < n; i++) {
            owner[i] = -1;
        }

        int[] saved = new int[n];
        int[] seen = new int[n];
        int stamp = 1;

        for (int source : initial) {
            for (int node = 0; node < n; node++) {
                if (infected[node] || graph[source][node] == 0) {
                    continue;
                }

                int root = find(parent, node);
                if (seen[root] == stamp) {
                    continue;
                }
                seen[root] = stamp;

                if (owner[root] == -1) {
                    owner[root] = source;
                } else {
                    owner[root] = -2;
                }
            }
            stamp++;
        }

        for (int i = 0; i < n; i++) {
            if (owner[i] >= 0) {
                saved[owner[i]] += size[i];
            }
        }

        int answer = initial[0];
        for (int node : initial) {
            if (saved[node] > saved[answer] ||
                (saved[node] == saved[answer] && node < answer)) {
                answer = node;
            }
        }

        return answer;
    }

    private int find(int[] parent, int node) {
        while (parent[node] != node) {
            parent[node] = parent[parent[node]];
            node = parent[node];
        }
        return node;
    }

    private void union(int[] parent, int[] size, int a, int b) {
        int rootA = find(parent, a);
        int rootB = find(parent, b);

        if (rootA == rootB) {
            return;
        }

        if (size[rootA] < size[rootB]) {
            int temp = rootA;
            rootA = rootB;
            rootB = temp;
        }

        parent[rootB] = rootA;
        size[rootA] += size[rootB];
    }
}
