class Solution {
    public int minAreaRect(int[][] points) {
        java.util.HashSet<Long> set = new java.util.HashSet<>();

        for (int[] point : points) {
            long key = ((long) point[0] << 32) | (point[1] & 0xffffffffL);
            set.add(key);
        }

        int minArea = Integer.MAX_VALUE;

        for (int i = 0; i < points.length; i++) {
            for (int j = i + 1; j < points.length; j++) {
                int x1 = points[i][0];
                int y1 = points[i][1];
                int x2 = points[j][0];
                int y2 = points[j][1];

                if (x1 == x2 || y1 == y2) {
                    continue;
                }

                long corner1 = ((long) x1 << 32) | (y2 & 0xffffffffL);
                long corner2 = ((long) x2 << 32) | (y1 & 0xffffffffL);

                if (set.contains(corner1) && set.contains(corner2)) {
                    int area = Math.abs(x1 - x2) * Math.abs(y1 - y2);
                    minArea = Math.min(minArea, area);
                }
            }
        }

        return minArea == Integer.MAX_VALUE ? 0 : minArea;
    }
}
