                    grid[i][j] = 0;
                    if (countIslands(grid) != 1) {
                        return 1;
                    }
                    grid[i][j] = 1;
                }
            }
        }

        return 2;
    }

    private int countIslands(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        boolean[][] visited = new boolean[m][n];
        int[] queue = new int[m * n];
        int islands = 0;
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 1 && !visited[r][c]) {
                    islands++;
                    if (islands > 1) {
                        return islands;
                    }

                    int head = 0;
                    int tail = 0;
                    queue[tail++] = r * n + c;
                    visited[r][c] = true;

                    while (head < tail) {
                        int cell = queue[head++];
                        int row = cell / n;
                        int col = cell % n;

                        for (int d = 0; d < 4; d++) {
                            int nr = row + dr[d];
                            int nc = col + dc[d];

                            if (nr >= 0 && nr < m && nc >= 0 && nc < n
                                    && grid[nr][nc] == 1 && !visited[nr][nc]) {
                                visited[nr][nc] = true;
                                queue[tail++] = nr * n + nc;
                            }
                        }
                    }
                }
            }
        }

        return islands;
    }
