    public int[] nextGreaterElements(int[] nums) {
        int n = nums.length;
        int[] result = new int[n];
        java.util.Arrays.fill(result, -1);

        int[] stack = new int[n];
        int top = 0;

        for (int i = 0; i < 2 * n; i++) {
            int current = nums[i % n];

            while (top > 0 && nums[stack[top - 1]] < current) {
                result[stack[--top]] = current;
            }

            if (i < n) {
                stack[top++] = i;
            }
        }

        return result;
    }
