class Solution {
    private int answer;
    private int target;

    public int nextBeautifulNumber(int n) {
        target = n;
        answer = Integer.MAX_VALUE;

        for (int mask = 1; mask < (1 << 9); mask++) {
            int length = 0;
            for (int digit = 1; digit <= 9; digit++) {
                if ((mask & (1 << (digit - 1))) != 0) {
                    length += digit;
                }
            }

            if (length <= 7) {
                int[] counts = new int[10];
                for (int digit = 1; digit <= 9; digit++) {
                    if ((mask & (1 << (digit - 1))) != 0) {
                        counts[digit] = digit;
                    }
                }
                generate(counts, length, 0);
            }
        }

        return answer;
    }

    private void generate(int[] counts, int remaining, int value) {
        if (remaining == 0) {
            if (value > target && value < answer) {
                answer = value;
            }
            return;
        }

        for (int digit = 1; digit <= 9; digit++) {
            if (counts[digit] > 0) {
                counts[digit]--;
                generate(counts, remaining - 1, value * 10 + digit);
                counts[digit]++;
            }
        }
    }
}
