import java.util.HashMap;
import java.util.Map;

class Solution {
    public int numTriplets(int[] nums1, int[] nums2) {
        return (int) (countWays(nums1, nums2) + countWays(nums2, nums1));
    }

    private long countWays(int[] source, int[] target) {
        Map<Integer, Integer> frequency = new HashMap<>();

        for (int value : target) {
            frequency.put(value, frequency.getOrDefault(value, 0) + 1);
        }

        long result = 0;

        for (int value : source) {
            long square = (long) value * value;

            for (Map.Entry<Integer, Integer> entry : frequency.entrySet()) {
                int first = entry.getKey();

                if (square % first != 0) {
                    continue;
                }

                long secondLong = square / first;
                if (secondLong < first || secondLong > Integer.MAX_VALUE) {
                    continue;
                }

                int second = (int) secondLong;
                Integer secondCount = frequency.get(second);

                if (secondCount == null) {
                    continue;
                }

                if (first == second) {
                    result += (long) entry.getValue() * (entry.getValue() - 1) / 2;
                } else {
                    result += (long) entry.getValue() * secondCount;
                }
            }
        }

        return result;
    }
}
