class Solution {
    public boolean canPartitionKSubsets(int[] nums, int k) {
        int total = 0;
        for (int num : nums) {
            total += num;
        }

        if (total % k != 0) {
            return false;
        }

        int target = total / k;
        Arrays.sort(nums);

        int n = nums.length;
        if (nums[n - 1] > target) {
            return false;
        }

        int fullMask = (1 << n) - 1;
        byte[] memo = new byte[1 << n];

        return dfs(nums, k, target, fullMask, 0, 0, memo);
    }

    private boolean dfs(int[] nums, int k, int target, int fullMask,
                        int mask, int currentSum, byte[] memo) {
        if (mask == fullMask) {
            return true;
        }

        if (memo[mask] != 0) {
            return memo[mask] == 1;
        }

        for (int i = nums.length - 1; i >= 0; i--) {
            if ((mask & (1 << i)) != 0) {
                continue;
            }

            if (currentSum + nums[i] > target) {
                continue;
            }

            int nextSum = currentSum + nums[i];
            int nextCurrentSum = nextSum == target ? 0 : nextSum;

            if (dfs(nums, k, target, fullMask, mask | (1 << i),
                    nextCurrentSum, memo)) {
                memo[mask] = 1;
                return true;
            }

            if (currentSum == 0) {
                break;
            }

            while (i > 0 && nums[i] == nums[i - 1]) {
                i--;
            }
        }

        memo[mask] = -1;
        return false;
    }
}
