        int total = 4 * n * n;
        int[] parent = new int[total];

        for (int i = 0; i < total; i++) {
            parent[i] = i;
        }

        int regions = total;

        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
