                    regions -= union(parent, base, base + 3);
                    regions -= union(parent, base + 1, base + 2);
                } else {
                    regions -= union(parent, base, base + 1);
                    regions -= union(parent, base + 2, base + 3);
                }

                if (r > 0) {
                    int above = ((r - 1) * n + c) * 4;
                    regions -= union(parent, base, above + 2);
                }

                if (c > 0) {
                    int left = (r * n + c - 1) * 4;
                    regions -= union(parent, base + 3, left + 1);
                }
            }
        }

