class Solution {
    private char[] a;
    private char[] b;
    private byte[][][] memo;

    public boolean isScramble(String s1, String s2) {
        int n = s1.length();
        if (n != s2.length()) {
            return false;
        }

        a = s1.toCharArray();
        b = s2.toCharArray();
        memo = new byte[n][n][n + 1];

        return dfs(0, 0, n);
    }

    private boolean dfs(int i, int j, int len) {
        if (memo[i][j][len] != 0) {
            return memo[i][j][len] == 2;
        }

        if (len == 1) {
            boolean result = a[i] == b[j];
            memo[i][j][len] = (byte) (result ? 2 : 1);
            return result;
        }

        int[] count = new int[26];
        for (int k = 0; k < len; k++) {
            count[a[i + k] - 'a']++;
            count[b[j + k] - 'a']--;
        }

        for (int value : count) {
            if (value != 0) {
                memo[i][j][len] = 1;
                return false;
            }
        }

        for (int split = 1; split < len; split++) {
            if (dfs(i, j, split) && dfs(i + split, j + split, len - split)) {
                memo[i][j][len] = 2;
                return true;
            }

            if (dfs(i, j + len - split, split) &&
                dfs(i + split, j, len - split)) {
                memo[i][j][len] = 2;
                return true;
            }
        }

        memo[i][j][len] = 1;
        return false;
    }
}
