class Solution {
    public List<List<String>> suggestedProducts(String[] products, String searchWord) {
        Arrays.sort(products);
        List<List<String>> result = new ArrayList<>();

        StringBuilder prefix = new StringBuilder();

        for (int i = 0; i < searchWord.length(); i++) {
            prefix.append(searchWord.charAt(i));
            String currentPrefix = prefix.toString();

            int left = 0;
            int right = products.length;

            while (left < right) {
                int mid = left + (right - left) / 2;
                if (products[mid].compareTo(currentPrefix) < 0) {
                    left = mid + 1;
                } else {
                    right = mid;
                }
            }

            List<String> suggestions = new ArrayList<>();
            for (int j = left; j < products.length && suggestions.size() < 3; j++) {
                if (products[j].startsWith(currentPrefix)) {
                    suggestions.add(products[j]);
                } else {
                    break;
                }
            }

            result.add(suggestions);
        }

        return result;
    }
}
