import java.util.TreeMap;

class Solution {
    private final TreeMap<Integer, Integer> low = new TreeMap<>();
    private final TreeMap<Integer, Integer> high = new TreeMap<>();
    private int lowSize;
    private int highSize;

    public double[] medianSlidingWindow(int[] nums, int k) {
        int n = nums.length;
        double[] result = new double[n - k + 1];

        for (int i = 0; i < k; i++) {
            add(nums[i]);
        }

        result[0] = median();

        for (int i = k; i < n; i++) {
            remove(nums[i - k]);
            add(nums[i]);
            result[i - k + 1] = median();
        }

        return result;
    }

    private void add(int value) {
        if (low.isEmpty() || value <= low.lastKey()) {
            increment(low, value);
            lowSize++;
        } else {
            increment(high, value);
            highSize++;
        }
        rebalance();
    }

    private void remove(int value) {
        if (!low.isEmpty() && value <= low.lastKey()) {
            decrement(low, value);
            lowSize--;
        } else {
            decrement(high, value);
            highSize--;
        }
        rebalance();
    }

    private void rebalance() {
        while (lowSize > highSize + 1) {
            int value = low.lastKey();
            decrement(low, value);
            lowSize--;
            increment(high, value);
            highSize++;
        }

        while (lowSize < highSize) {
            int value = high.firstKey();
            decrement(high, value);
            highSize--;
            increment(low, value);
            lowSize++;
        }
    }

    private double median() {
        if ((lowSize + highSize) % 2 == 1) {
            return low.lastKey();
        }
        return ((double) low.lastKey() + (double) high.firstKey()) / 2.0;
    }

    private void increment(TreeMap<Integer, Integer> map, int value) {
        map.put(value, map.getOrDefault(value, 0) + 1);
    }

    private void decrement(TreeMap<Integer, Integer> map, int value) {
        int count = map.get(value);
        if (count == 1) {
            map.remove(value);
        } else {
            map.put(value, count - 1);
        }
    }
}
