class Solution {
    public int minStickers(String[] stickers, String target) {
        int m = target.length();
        int fullMask = (1 << m) - 1;
        int[][] counts = new int[stickers.length][26];

        for (int i = 0; i < stickers.length; i++) {
            for (int j = 0; j < stickers[i].length(); j++) {
                counts[i][stickers[i].charAt(j) - 'a']++;
            }
        }

        int[] dp = new int[1 << m];
        int inf = Integer.MAX_VALUE / 2;
        java.util.Arrays.fill(dp, inf);
        dp[0] = 0;

        for (int mask = 0; mask <= fullMask; mask++) {
            if (dp[mask] == inf) {
                continue;
            }

            for (int[] sticker : counts) {
                int[] remaining = sticker.clone();
                int nextMask = mask;

                for (int i = 0; i < m; i++) {
                    if ((nextMask & (1 << i)) == 0) {
                        int letter = target.charAt(i) - 'a';
                        if (remaining[letter] > 0) {
                            remaining[letter]--;
                            nextMask |= 1 << i;
                        }
                    }
                }

                if (nextMask != mask) {
                    dp[nextMask] = Math.min(dp[nextMask], dp[mask] + 1);
                }
            }
        }

        return dp[fullMask] == inf ? -1 : dp[fullMask];
    }
}
