class Solution {
    private int[][][] minMemo = new int[29][29][29];
    private int[][][] maxMemo = new int[29][29][29];

    public int[] earliestAndLatest(int n, int firstPlayer, int secondPlayer) {
        return dfs(n, firstPlayer, secondPlayer);
    }

    private int[] dfs(int n, int a, int b) {
        if (a + b == n + 1) {
            return new int[]{1, 1};
        }

        if (minMemo[n][a][b] != 0) {
            return new int[]{minMemo[n][a][b], maxMemo[n][a][b]};
        }

        int earliest = Integer.MAX_VALUE;
        int latest = 0;

        int pairCount = n / 2;
        int totalMasks = 1 << pairCount;

        for (int mask = 0; mask < totalMasks; mask++) {
            int lessThanA = 0;
            int lessThanB = 0;

            for (int i = 0; i < pairCount; i++) {
                int left = i + 1;
                int right = n - i;

                int winner;
                if (left == a || right == a) {
                    winner = a;
                } else if (left == b || right == b) {
                    winner = b;
                } else {
                    winner = ((mask & (1 << i)) == 0) ? left : right;
                }

                if (winner < a) {
                    lessThanA++;
                }
                if (winner < b) {
                    lessThanB++;
                }
            }

            if ((n & 1) == 1) {
                int middle = (n + 1) / 2;
                if (middle < a) {
                    lessThanA++;
                }
                if (middle < b) {
                    lessThanB++;
                }
            }

            int nextA = lessThanA + 1;
            int nextB = lessThanB + 1;

            int[] result = dfs((n + 1) / 2, nextA, nextB);
            earliest = Math.min(earliest, result[0] + 1);
            latest = Math.max(latest, result[1] + 1);
        }

        minMemo[n][a][b] = earliest;
        maxMemo[n][a][b] = latest;

        return new int[]{earliest, latest};
    }
}
