import java.util.Arrays;

class Solution {
    public int[] getCoprimes(int[] nums, int[][] edges) {
        int n = nums.length;
        int[] head = new int[n];
        Arrays.fill(head, -1);

        int[] to = new int[2 * (n - 1)];
        int[] next = new int[2 * (n - 1)];
        int edgeIndex = 0;

        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];

            to[edgeIndex] = v;
            next[edgeIndex] = head[u];
            head[u] = edgeIndex++;

            to[edgeIndex] = u;
            next[edgeIndex] = head[v];
            head[v] = edgeIndex++;
        }

        boolean[][] coprime = new boolean[51][51];
        for (int i = 1; i <= 50; i++) {
            for (int j = 1; j <= 50; j++) {
                coprime[i][j] = gcd(i, j) == 1;
            }
        }

        int[] answer = new int[n];
        int[] depth = new int[n];
        int[] previous = new int[n];
        int[] top = new int[51];
        Arrays.fill(top, -1);

        int[] stackNode = new int[2 * n + 5];
        int[] stackParent = new int[2 * n + 5];
        boolean[] stackExit = new boolean[2 * n + 5];

        int stackSize = 0;
        stackNode[stackSize] = 0;
        stackParent[stackSize] = -1;
        stackExit[stackSize++] = false;

        while (stackSize > 0) {
            --stackSize;
            int node = stackNode[stackSize];
            int parent = stackParent[stackSize];

            if (stackExit[stackSize]) {
                top[nums[node]] = previous[node];
                continue;
            }

            int best = -1;
            int value = nums[node];

            for (int candidateValue = 1; candidateValue <= 50; candidateValue++) {
                int candidate = top[candidateValue];
                if (candidate != -1 && coprime[value][candidateValue]) {
                    if (best == -1 || depth[candidate] > depth[best]) {
                        best = candidate;
                    }
                }
            }

            answer[node] = best;

            previous[node] = top[value];
            top[value] = node;

            stackNode[stackSize] = node;
            stackParent[stackSize] = parent;
            stackExit[stackSize++] = true;

            for (int edge = head[node]; edge != -1; edge = next[edge]) {
                int neighbor = to[edge];
                if (neighbor == parent) {
                    continue;
                }

                depth[neighbor] = depth[node] + 1;
                stackNode[stackSize] = neighbor;
                stackParent[stackSize] = node;
                stackExit[stackSize++] = false;
            }
        }

        return answer;
    }

    private int gcd(int a, int b) {
        while (b != 0) {
            int temp = a % b;
            a = b;
            b = temp;
        }
        return a;
    }
}
