    private String[] words;
    private String result;
    private int maxLen;
    private int[] digit;
    private boolean[] used;
    private boolean[] leading;

    public boolean isSolvable(String[] words, String result) {
        this.words = words;
        this.result = result;
        this.maxLen = result.length();
        this.digit = new int[26];
        this.used = new boolean[10];
        this.leading = new boolean[26];

        java.util.Arrays.fill(digit, -1);

        for (String word : words) {
            maxLen = Math.max(maxLen, word.length());
            if (word.length() > 1) {
                leading[word.charAt(0) - 'A'] = true;
            }
        }

        if (result.length() > 1) {
            leading[result.charAt(0) - 'A'] = true;
        }

        return dfs(0, 0, 0);
    }

    private boolean dfs(int column, int index, int sum) {
        if (column == maxLen) {
            return sum == 0;
        }

        if (index < words.length) {
            String word = words[index];

            if (column >= word.length()) {
                return dfs(column, index + 1, sum);
            }

            int c = word.charAt(word.length() - 1 - column) - 'A';

            if (digit[c] != -1) {
                return dfs(column, index + 1, sum + digit[c]);
            }

            for (int d = 0; d <= 9; d++) {
                if (used[d] || (d == 0 && leading[c])) {
                    continue;
                }

                digit[c] = d;
                used[d] = true;

                if (dfs(column, index + 1, sum + d)) {
                    return true;
                }

                digit[c] = -1;
                used[d] = false;
            }

            return false;
        }

        int required = sum % 10;
        int nextCarry = sum / 10;

        if (column >= result.length()) {
            return required == 0 && dfs(column + 1, 0, nextCarry);
        }

        int c = result.charAt(result.length() - 1 - column) - 'A';

        if (digit[c] != -1) {
            return digit[c] == required
                    && dfs(column + 1, 0, nextCarry);
        }

        if (used[required] || (required == 0 && leading[c])) {
            return false;
        }

        digit[c] = required;
        used[required] = true;

        if (dfs(column + 1, 0, nextCarry)) {
            return true;
        }

        digit[c] = -1;
        used[required] = false;
        return false;
    }
